local ui=require("ui");local hw=require("hw");local M={};local db="zevelian_music.db"
local function load() if not fs.exists(db) then return {} end local f=fs.open(db,"r");local s=f.readAll();f.close();local ok,t=pcall(textutils.unserialize,s);return ok and type(t)=="table" and t or {} end
local function save(t) local f=fs.open(db,"w");f.write(textutils.serialize(t));f.close() end
local function play(sp,url) if not sp then return false,"No Speaker installed." end;if not url:match("%.dfpwm([?#].*)?$") then return false,"Use a direct .dfpwm audio URL." end;local ok,h=pcall(http.get,url,nil,true);if not ok or not h then return false,"Audio download failed." end;local dec=cc.audio.dfpwm.make_decoder();while true do local chunk=h.read(16384);if not chunk or #chunk==0 then break end;local data=dec(chunk);while not sp.playAudio(data) do os.pullEvent("speaker_audio_empty") end end;h.close();return true end
function M.run(m) local t=load();local sp=hw.speaker();while true do ui.clear(m);ui.header(m,"MUSIC LIBRARY");local w,h=m.getSize();m.setCursorPos(2,3);m.write(sp and "Speaker: ONLINE" or "Speaker: NOT INSTALLED");if #t==0 then m.setCursorPos(2,5);m.write("Library empty.") else for i,v in ipairs(t) do if i+4>=h then break end;m.setCursorPos(2,4+i);m.write((i..". "..tostring(v.title)):sub(1,w-2)) end end;local bw=math.max(10,math.floor(w/3));ui.btn(m,1,h,bw,"ADD URL",false);ui.btn(m,1+bw,h,bw,"PLAY 1",false);ui.btn(m,1+bw*2,h,w-(1+bw*2)+1,"BACK",false);local _,x,y=os.pullEvent("monitor_touch");if y==h then if x<=bw then term.write("Direct DFPWM URL: ");local u=read();if u~="" then term.write("Title: ");local n=read();t[#t+1]={url=u,title=n~="" and n or u};save(t) end elseif x<=bw*2 and t[1] then local ok,e=play(sp,t[1].url);if not ok then m.setCursorPos(2,3);m.write(e);sleep(2) end else return end end end end
return M
